CREATE TABLE IF NOT EXISTS "system_electronic_signature" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "module_code" varchar(64) not null,
    "action_code" varchar(64) not null,
    "subject_type" varchar(64) not null,
    "subject_id" varchar(512) not null,
    "subject_version" varchar(128) not null,
    "actor_id" bigint not null,
    "meaning_code" varchar(64) not null,
    "meaning_label" varchar(128) not null,
    "reason" varchar(500) not null,
    "signed_at" timestamp not null,
    "time_evidence_id" varchar(128) not null,
    "authentication_method" varchar(64) not null,
    "content_hash" char(64) not null,
    "before_content_hash" char(64),
    "after_content_hash" char(64),
    "canonical_content_json" varchar(4000) not null,
    "before_content_json" varchar(4000),
    "after_content_json" varchar(4000),
    "field_diff_json" varchar(4000),
    "evidence_hash" char(64) not null,
    "algorithm" varchar(32) not null,
    "key_version" varchar(64) not null,
    "policy_version" varchar(64) not null,
    "verification_status" varchar(32) not null,
    "idempotency_key" varchar(128) not null,
    "command_hash" char(64) not null,
    "process_instance_id" varchar(128),
    "task_id" varchar(128),
    "node_code" varchar(64),
    "node_order" int,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id"),
    unique ("tenant_id", "idempotency_key", "deleted")
);

CREATE TABLE IF NOT EXISTS "system_electronic_signature_review" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "review_type" varchar(32) not null,
    "review_scope" varchar(128) not null,
    "trigger_reason" varchar(256) not null,
    "status" varchar(32) not null,
    "owner_user_id" bigint not null,
    "backup_owner_user_id" bigint not null,
    "sop_version" varchar(64) not null,
    "training_evidence_id" varchar(128) not null,
    "planned_at" timestamp not null,
    "due_at" timestamp not null,
    "escalated_at" timestamp,
    "escalated_to_user_id" bigint,
    "completed_at" timestamp,
    "completed_by" bigint,
    "sample_rule_json" varchar(4000) not null,
    "result_summary_json" varchar(4000),
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id")
);

CREATE TABLE IF NOT EXISTS "system_electronic_signature_time_evidence" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "trusted_time_source" varchar(128) not null,
    "source_reported_at" timestamp not null,
    "server_observed_at" timestamp not null,
    "drift_millis" bigint not null,
    "evidence_hash" char(64) not null,
    "status" varchar(32) not null,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id")
);

CREATE TABLE IF NOT EXISTS "system_electronic_signature_seal" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "seal_date" date not null,
    "record_count" int not null,
    "first_signature_id" bigint not null,
    "last_signature_id" bigint not null,
    "previous_seal_hash" char(64),
    "seal_hash" char(64) not null,
    "worm_evidence_id" varchar(128) not null,
    "status" varchar(32) not null,
    "sealed_at" timestamp not null,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id"),
    unique ("tenant_id", "seal_date", "deleted")
);

CREATE TABLE IF NOT EXISTS "system_electronic_signature_privileged_audit" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "reviewer_user_id" bigint not null,
    "operation_code" varchar(128) not null,
    "reason" varchar(500) not null,
    "result_status" varchar(32) not null,
    "evidence_hash" char(64) not null,
    "audited_at" timestamp not null,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id")
);

CREATE TABLE IF NOT EXISTS "system_electronic_signature_archive_recovery" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "archive_id" bigint not null,
    "restored_at" timestamp not null,
    "restored_by" bigint not null,
    "business_record_hash" char(64) not null,
    "signature_record_hash" char(64) not null,
    "snapshot_hash" char(64) not null,
    "restore_evidence_hash" char(64) not null,
    "result_status" varchar(32) not null,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id")
);
